import fs from 'node:fs';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { normalizeProposal, proposedEntry, contentHash } from 'C:/Users/user/orca/workspaces/todays-math/student-clear-integration-20261006/scripts/qa/concept-blank/student-clear/proposals.ts';
import { workerFingerprint } from 'C:/Users/user/orca/workspaces/todays-math/student-clear-integration-20261006/scripts/qa/concept-blank/student-clear/editorial.ts';
import { bankNotationFaults } from 'C:/Users/user/orca/workspaces/todays-math/student-clear-integration-20261006/src/lib/concept-blank/notation.ts';
import { blankKeywords, splitBlankSentence } from 'C:/Users/user/orca/workspaces/todays-math/student-clear-integration-20261006/src/contracts/conceptBlank.contract.ts';
const out='C:/Users/user/orca/workspaces/todays-math/student-clear-e3e4-20261006/docs/planning/tracks/reports/concept-student-clear-20261006/middle-assist-remaining-380';
const auditPath='C:/Users/user/orca/workspaces/todays-math/student-clear-m1m2m3-20261006/docs/planning/tracks/reports/concept-student-clear-20261006/m1m2m3/audit.json';
const baselinePath='D:/tmp/concept-student-clear-20261006/baseline.json';
const hash=(s:Buffer|string)=>createHash('sha256').update(s).digest('hex');
const json=(p:string)=>JSON.parse(fs.readFileSync(p,'utf8'));
const write=(p:string,v:any)=>fs.writeFileSync(path.join(out,p),JSON.stringify(v,null,2)+'\n','utf8');
const now=()=>new Date().toISOString();
const scope=(i:number)=>(i>=2900&&i<=2999)||(i>=3120&&i<=3399);
const [mode,a,b]=process.argv.slice(2);
if(mode==='init'){
 fs.mkdirSync(path.join(out,'evidence'),{recursive:true});
 const auditBytes=fs.readFileSync(auditPath), baselineBytes=fs.readFileSync(baselinePath);
 const baseline=JSON.parse(baselineBytes.toString('utf8'));
 const originals=new Map(Object.values(baseline.parts).flatMap((p:any)=>p.concepts).map((e:any)=>[e.id,e]));
 const rows=JSON.parse(auditBytes.toString('utf8')).rows.filter((r:any)=>scope(r.sourceIndex)).sort((x:any,y:any)=>x.sourceIndex-y.sourceIndex);
 if(rows.length!==380)throw Error('Scope count '+rows.length);
 const inputs=rows.map((raw:any)=>{
  const original:any=originals.get(raw.id);if(!original)throw Error(raw.id);
  const normalized=normalizeProposal(raw,original);if(!normalized)throw Error('Incomplete '+raw.id);
  return {id:raw.id,sourceIndex:raw.sourceIndex,raw,rawSha256:contentHash(raw),currentRawFingerprint:workerFingerprint('middle',raw),original,definitionSha256:hash(original.definition),originalSha256:contentHash(original),normalized,normalizedHash:normalized.hash};
 });
 write('evidence/inputs.json',{capturedAt:now(),auditPath,auditSha256:hash(auditBytes),baselinePath,baselineSha256:hash(baselineBytes),sourceCommit:baseline.sourceCommit,fingerprint:'workerFingerprint(middle,row): JS designated field order; assembled content additionally protected by rawSha256 and normalizedHash',inputs});
 fs.writeFileSync(path.join(out,'.gitattributes'),'* -text\nevidence/** -text\n','utf8');
 textInit:console.log(JSON.stringify({count:inputs.length,first:inputs[0].id,last:inputs.at(-1).id,auditSha256:hash(auditBytes)}));
} else if(mode==='read'){
 const inputs=json(path.join(out,'evidence/inputs.json')).inputs.filter((x:any)=>x.sourceIndex>=+a&&x.sourceIndex<=+b);
 if(inputs.length>25||!inputs.length)throw Error('Read batch count');
 const at=now();let s=`\nBATCH ${a}-${b} | ${at} | ${inputs.length} rows | evidence/inputs.json\n`;
 for(const x of inputs){const n=x.normalized;s+=JSON.stringify({i:x.sourceIndex,id:x.id,role:x.raw.learningRole,term:x.original.term,level:x.original.level,definition:x.original.definition,coreAfter:n.coreAfter,coreReason:n.coreReason,B:n.B,C:n.C})+'\n';}
 fs.appendFileSync(path.join(out,'evidence/reading-batches.txt'),s,'utf8'); console.log(s);
} else if(mode==='record'||mode==='amend'){
 const capture=json(path.join(out,'evidence/inputs.json'));
 const draft=json(a);const inputs=capture.inputs;const at=now();
 const records=draft.map((d:any)=>{
  const x=inputs.find((v:any)=>v.sourceIndex===d.i);if(!x)throw Error('Out of scope '+d.i);
  if(!d.b||!d.c||!d.core)throw Error('Missing manual reason '+d.i);
  let n:any=null,issues:any=[];
  if(d.patch){n=normalizeProposal({...x.raw,...d.patch},x.original);if(!n)throw Error('Incomplete patch '+d.i);issues=bankNotationFaults({concepts:[proposedEntry(n)],ox:[],apply:[],figures:[]});}
  const fullPatch=d.patch?{...d.patch,bDecision:'excluded' in n.B?'exclude':({...x.raw,...d.patch}).bDecision,cDecision:'excluded' in n.C?'exclude':({...x.raw,...d.patch}).cDecision,bQuestion:'excluded' in n.B?null:n.B,clozeQuestion:'excluded' in n.C?null:n.C,coreAfter:n.coreAfter,coreReason:n.coreReason,questionExclusions:{...('excluded' in n.B?{term:n.B.excluded}:{}),...('excluded' in n.C?{cloze:n.C.excluded}:{})}}:undefined;
  return {id:x.id,sourceIndex:x.sourceIndex,currentRawFingerprint:x.currentRawFingerprint,normalizedHash:x.normalizedHash,learningRole:x.raw.learningRole,bVerdict:d.bVerdict??'adopt',cVerdict:d.cVerdict??'adopt',coreVerdict:d.coreVerdict??'adopt',bReason:d.b,cReason:d.c,coreReason:d.core,inputEvidence:'evidence/inputs.json#'+x.sourceIndex,inputSha256:x.rawSha256,recordedAfterDirectReading:'Codex direct reading of printed normalized B/C, all required ideas and accepted answers, original definition and existing coreAfter; proposal is not primary-applied approval',readAt:at,...(d.patch?{proposedPatch:fullPatch,proposedNormalizedHash:n.hash,proposalStatus:'pending-primary-application-and-final-reread'}:{})};
 });
 fs.appendFileSync(path.join(out,'evidence/manual-decisions.jsonl'),JSON.stringify({recordedAt:at,sourceFile:a,manualDraft:draft,records})+'\n','utf8');
 const old=fs.existsSync(path.join(out,'reviews.json'))?json(path.join(out,'reviews.json')):[];
 for(const r of records){const i=old.findIndex((v:any)=>v.id===r.id);if(i>=0){if(mode!=='amend')throw Error('Duplicate '+r.id);old[i]=r;}else old.push(r);}
 write('reviews.json',old.sort((x:any,y:any)=>x.sourceIndex-y.sourceIndex));
 let s=`\nPROPOSAL REREAD ${at}\n`;
 for(const d of draft.filter((d:any)=>d.patch)){const x=inputs.find((v:any)=>v.sourceIndex===d.i),n=normalizeProposal({...x.raw,...d.patch},x.original)!;s+=JSON.stringify({i:d.i,id:x.id,B:n.B,C:n.C,coreAfter:n.coreAfter,coreReason:n.coreReason,hash:n.hash,notation:bankNotationFaults({concepts:[proposedEntry(n)],ox:[],apply:[],figures:[]})})+'\n';}
 fs.appendFileSync(path.join(out,'evidence/proposal-reread.txt'),s,'utf8');console.log(s);console.log('RECORDED '+records.length+' TOTAL '+old.length);
} else if(mode==='final'){
 const capture=json(path.join(out,'evidence/inputs.json')),reviews=json(path.join(out,'reviews.json'));
 const immutableErrors:any[]=[];
 for(const r of reviews){const x=capture.inputs.find((x:any)=>x.id===r.id);if(!x){immutableErrors.push({id:r.id,error:'unexpected id'});continue;}const n=normalizeProposal({...x.raw,...r.proposedPatch},x.original)!;
  const entry:any=proposedEntry(n);
  for(const key of ['id','section','term','kind','level','example','givenCase'])if(JSON.stringify(entry[key])!==JSON.stringify(x.original[key]))immutableErrors.push({id:r.id,error:'immutable '+key});
  if(r.sourceIndex!==x.sourceIndex||r.learningRole!==x.raw.learningRole)immutableErrors.push({id:r.id,error:'source order or learningRole'});
  if(r.proposedPatch){if(n.hash!==r.proposedNormalizedHash)immutableErrors.push({id:r.id,error:'candidate hash changed after normalized reread'});
   r.proposedPatch={...r.proposedPatch,bDecision:'excluded' in n.B?'exclude':('prompt' in x.normalized.B&&contentHash(n.B)===contentHash(x.normalized.B)?x.raw.bDecision:'rewrite'),cDecision:'excluded' in n.C?'exclude':('sentence' in x.normalized.C&&contentHash(n.C)===contentHash(x.normalized.C)?x.raw.cDecision:'rewrite'),bQuestion:'excluded' in n.B?null:n.B,clozeQuestion:'excluded' in n.C?null:n.C,...('prompt' in n.B?{bPrompt:n.B.prompt,bAnswer:n.B.answer,bRequiredIdeas:n.B.requiredIdeas}:{}),...('sentence' in n.C?{cMarkedSentence:n.C.sentence,cAfter:n.C.sentence,cAcceptedAnswers:n.C.acceptedAnswers,cSlotAnswers:blankKeywords(n.C.sentence),cStudentSentence:splitBlankSentence(n.C.sentence).map(p=>p.kind==='key'?'□':p.text).join('')}:{}),coreAfter:n.coreAfter,coreReason:n.coreReason,questionExclusions:{...('excluded' in n.B?{term:n.B.excluded}:{}),...('excluded' in n.C?{cloze:n.C.excluded}:{})}};
   r.proposalRereadRecordedAt=now();r.proposalRereadEvidence='evidence/proposal-reread.txt';r.proposedEffectiveDefinition=entry.definition;
  }
 }
 write('reviews.json',reviews);
 const auditBytes=fs.readFileSync(auditPath),current=JSON.parse(auditBytes.toString('utf8')).rows;
 const comparison=capture.inputs.map((x:any)=>{const r=current.find((r:any)=>r.id===x.id);const n=r&&normalizeProposal(r,x.original);return {id:x.id,sourceIndex:x.sourceIndex,rawSha256Before:x.rawSha256,rawSha256Now:r&&contentHash(r),fingerprintBefore:x.currentRawFingerprint,fingerprintNow:r&&workerFingerprint('middle',r),normalizedHashBefore:x.normalizedHash,normalizedHashNow:n?.hash,unchanged:!!r&&r.sourceIndex===x.sourceIndex&&contentHash(r)===x.rawSha256&&workerFingerprint('middle',r)===x.currentRawFingerprint&&n?.hash===x.normalizedHash};});
 write('evidence/current-comparison.json',{checkedAt:now(),auditPath,auditSha256AtCapture:capture.auditSha256,auditSha256Now:hash(auditBytes),rows:comparison,changedIds:comparison.filter((x:any)=>!x.unchanged).map((x:any)=>x.id)});
 const errors:any[]=[],before:any[]=[],after:any[]=[],patchIds:string[]=[];
 for(const x of capture.inputs){const r=reviews.find((r:any)=>r.id===x.id);if(!r){errors.push({id:x.id,error:'missing manual record'});continue;}try{const n=normalizeProposal({...x.raw,...r.proposedPatch},x.original)!;proposedEntry(n);const f=bankNotationFaults({concepts:[proposedEntry(n)],ox:[],apply:[],figures:[]});after.push(...f);before.push(...bankNotationFaults({concepts:[proposedEntry(x.normalized)],ox:[],apply:[],figures:[]}));if(r.proposedPatch)patchIds.push(r.id);}catch(e){errors.push({id:x.id,error:String(e)});}}
 const readText=fs.readFileSync(path.join(out,'evidence/reading-batches.txt'),'utf8');
 const headers=[...readText.matchAll(/BATCH (\d+)-(\d+) \| ([^|]+) \| (\d+) rows/g)].map(m=>({from:+m[1],to:+m[2],at:m[3].trim(),count:+m[4],file:'evidence/reading-batches.txt'}));
 const readRows=readText.split('\n').filter(s=>s.startsWith('{')).map(s=>JSON.parse(s));
 const readIds=new Set(readRows.map(r=>r.id));
 const toolsPaths=['C:/Users/user/orca/workspaces/todays-math/student-clear-integration-20261006/scripts/qa/concept-blank/student-clear/proposals.ts','C:/Users/user/orca/workspaces/todays-math/student-clear-integration-20261006/scripts/qa/concept-blank/student-clear/editorial.ts','C:/Users/user/orca/workspaces/todays-math/student-clear-integration-20261006/src/contracts/conceptBlank.contract.ts','C:/Users/user/orca/workspaces/todays-math/student-clear-integration-20261006/src/lib/concept-blank/notation.ts'];
 write('evidence/validation.json',{checkedAt:now(),count:reviews.length,expected:380,unwritten:380-reviews.length,patchCount:patchIds.length,patchIds,contractErrors:errors,immutableErrors,baselineUnchanged:hash(fs.readFileSync(baselinePath))===capture.baselineSha256,reading:{batchCount:headers.length,maxBatch:Math.max(...headers.map(h=>h.count)),printedRows:readRows.length,uniqueIds:readIds.size,allScopePrinted:capture.inputs.every((x:any)=>readIds.has(x.id)),batches:headers,disclosure:'These are actual printed normalized input batches, followed by ID-specific human-authored Codex judgments in manual-decisions.jsonl; no iteration or schema pass is counted as reading.'},notationBefore:before,notationAfter:after,currentChanged:comparison.filter((x:any)=>!x.unchanged),toolchain:toolsPaths.map(p=>({path:p,sha256:hash(fs.readFileSync(p))})),helper:{path:'D:/tmp/concept-student-clear-20261006/middle-assist-remaining-380-helper.ts',source:fs.readFileSync('D:/tmp/concept-student-clear-20261006/middle-assist-remaining-380-helper.ts','utf8')},status:'direct-reading-and-proposal-only; not independent Claude approval, student effect experiment, primary application, or production release'});
 console.log(JSON.stringify({count:reviews.length,patchCount:patchIds.length,unwritten:380-reviews.length,contractErrors:errors.length,immutableErrors:immutableErrors.length,notationBefore:before.length,notationAfter:after.length,changed:comparison.filter((x:any)=>!x.unchanged).length,readingBatches:headers.length,printed:readRows.length}));
} else if(mode==='manifest'){
 const files=['.gitattributes','REPORT.md','reviews.json','evidence/inputs.json','evidence/reading-batches.txt','evidence/manual-decisions.jsonl','evidence/proposal-reread.txt','evidence/validation.json','evidence/current-comparison.json'];
 write('evidence/manifest.json',{createdAt:now(),algorithm:'SHA-256 of exact file bytes; manifest excluded from self-hash',files:files.map(p=>({path:p,bytes:fs.statSync(path.join(out,p)).size,sha256:hash(fs.readFileSync(path.join(out,p)))}))});console.log('manifest '+files.length);
}else throw Error('unknown mode');
